CREATE TABLE `account_statements` (
	`id` text PRIMARY KEY NOT NULL,
	`owner_id` text NOT NULL,
	`account_id` text NOT NULL,
	`title` text NOT NULL,
	`currency` text NOT NULL,
	`period_start` text NOT NULL,
	`period_end` text NOT NULL,
	`opening_balance` integer,
	`closing_balance` integer,
	`notes` text DEFAULT '' NOT NULL,
	`created_at` text NOT NULL,
	`completed_at` text,
	`snapshot_opening` integer,
	`snapshot_closing` integer,
	`review_required` integer DEFAULT 0 NOT NULL,
	`adjustment_type` text,
	`adjustment_id` text,
	`adjustment_before` text,
	`adjustment_after` text,
	FOREIGN KEY (`owner_id`,`account_id`) REFERENCES `accounts`(`owner_id`,`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "statement_period" CHECK("account_statements"."period_end" >= "account_statements"."period_start"),
	CONSTRAINT "statement_amounts" CHECK(("account_statements"."opening_balance" IS NULL OR abs("account_statements"."opening_balance")<=1000000000000) AND ("account_statements"."closing_balance" IS NULL OR abs("account_statements"."closing_balance")<=1000000000000) AND ("account_statements"."opening_balance" IS NOT NULL OR "account_statements"."closing_balance" IS NOT NULL))
);
